import javax.swing.*;import java.awt.*;import java.sql.*;import java.util.*;
public class VotingWindow extends JFrame {
    static final String[] POS={"General Secretary","Sports Secretary","Vice President","Event Secretary"};User user;Map<String,ButtonGroup> groups=new LinkedHashMap<>();Map<String,Map<String,String>> options=new LinkedHashMap<>();int seconds=60;JLabel clock=new JLabel("Time left: 60 seconds");javax.swing.Timer timer;
    public VotingWindow(User u){user=u;setTitle("Voting Ballot");setExtendedState(MAXIMIZED_BOTH);setDefaultCloseOperation(DO_NOTHING_ON_CLOSE);JPanel root=UI.panel();root.setLayout(new BorderLayout());JLabel title=new JLabel("COLLEGE ELECTION BALLOT",SwingConstants.CENTER);title.setForeground(Color.WHITE);title.setFont(new Font("SansSerif",Font.BOLD,26));root.add(title,BorderLayout.NORTH);clock.setForeground(Color.YELLOW);clock.setFont(new Font("SansSerif",Font.BOLD,18));root.add(clock,BorderLayout.SOUTH);JPanel ballot=new JPanel();ballot.setBackground(Color.WHITE);ballot.setLayout(new BoxLayout(ballot,BoxLayout.Y_AXIS));
        try(Connection c=DbConfig.connect()){for(String pos:POS){ButtonGroup bg=new ButtonGroup();groups.put(pos,bg);Map<String,String> map=new LinkedHashMap<>();map.put("None","None");JPanel section=new JPanel(new FlowLayout(FlowLayout.LEFT));section.setBorder(BorderFactory.createTitledBorder(pos));section.setBackground(Color.WHITE);JRadioButton none=new JRadioButton("None",true);none.setBackground(Color.WHITE);bg.add(none);section.add(none);try(PreparedStatement s=c.prepareStatement("SELECT student_id,candidate_name FROM Candidates WHERE position=? ORDER BY candidate_name")){s.setString(1,pos);try(ResultSet r=s.executeQuery()){while(r.next()){map.put(r.getString(1),r.getString(2));JRadioButton b=new JRadioButton(r.getString(2));b.setBackground(Color.WHITE);b.putClientProperty("candidateId",r.getString(1));bg.add(b);section.add(b);}}}options.put(pos,map);ballot.add(section);}}catch(Exception e){UI.error(this,e);dispose();return;}
        JScrollPane scroll=new JScrollPane(ballot);root.add(scroll,BorderLayout.CENTER);JButton submit=UI.button("SUBMIT BALLOT");root.add(submit,BorderLayout.EAST);submit.addActionListener(e->submit());add(root);timer=new javax.swing.Timer(1000,e->{seconds--;clock.setText("Time left: "+seconds+" seconds");if(seconds<=0)submit();});timer.start();}
    private void submit(){if(timer!=null)timer.stop();Map<String,String> chosen=new LinkedHashMap<>();for(String pos:POS){String selected="None";for(Enumeration<AbstractButton> en=groups.get(pos).getElements();en.hasMoreElements();){AbstractButton b=en.nextElement();if(b.isSelected()&&b instanceof JRadioButton){Object id=((JRadioButton)b).getClientProperty("candidateId");if(id!=null)selected=id.toString();}}chosen.put(pos,selected);}
        try(Connection c=DbConfig.connect()){if(!"active".equals(UI.electionStatus())){UI.msg(this,"Election has been stopped. Ballot not saved.");new Login().setVisible(true);dispose();return;}c.setAutoCommit(false);try(PreparedStatement s=c.prepareStatement("UPDATE Candidates SET votes=votes+1 WHERE student_id=? AND position=?")){for(String pos:POS){String id=chosen.get(pos);if(!"None".equals(id)){s.setString(1,id);s.setString(2,pos);s.addBatch();}}s.executeBatch();}c.commit();new ResultWindow(user,chosen).setVisible(true);dispose();}catch(Exception e){UI.error(this,e);}
    }
}
